def solve_graph():
    # Use a class to hold state
    class State:
        pass

    s = State()
    s.domains = [{0,1,2} for _ in range(n)]
    s.assigned = [-1] * n

    def ac3():
        queue = [(u,v) for (u,v) in edges] + [(v,u) for (u,v) in edges]
        while queue:
            u, v = queue.pop(0)
            if revise(u, v):
                if len(s.domains[u]) == 0:
                    return False
                for w in adj[u]:
                    if w != v:
                        queue.append((w, u))
        return True

    def revise(u, v):
        revised = False
        to_remove = set()
        for c in s.domains[u]:
            # Check if there is at least one color in domain of v different from c
            # Actually, support means there exists some color in v's domain that is != c
            # If v's domain has only one color and it equals c, then c has no support
            if len(s.domains[v]) == 1 and next(iter(s.domains[v])) == c:
                to_remove.add(c)
                revised = True
        if revised:
            s.domains[u] -= to_remove
        return revised

    if not ac3():
        return None

    best_solution = [None]

    def backtrack():
        # Check if all assigned
        if all(s.assigned[v] != -1 for v in range(n)):
            best_solution[0] = s.assigned[:]
            return True

        # Choose variable with smallest domain
        min_size = 4
        best_v = -1
        for v in range(n):
            if s.assigned[v] == -1:
                sz = len(s.domains[v])
                if sz < min_size:
                    min_size = sz
                    best_v = v
                    if sz == 1:
                        break

        v = best_v
        if min_size == 0:
            return False

        # Try each color in domain (copy list to avoid modification during iteration)
        for c in sorted(s.domains[v]):
            # Save state
            saved_domains = [set(d) for d in s.domains]
            saved_assigned = s.assigned[:]

            # Assign
            s.assigned[v] = c
            s.domains[v] = {c}

            # Run AC-3
            if ac3():
                if backtrack():
                    return True

            # Restore
            s.domains = saved_domains
            s.assigned = saved_assigned

        return False

    if backtrack():
        return best_solution[0]
    return None

